(51, 8, 16, 'Professional Blood Pressure Monitor', 'HEM-907XL', 'Clinical BP monitor with auto and manual modes and three cuff sizes. Some scuffs on the housing; tested and working. Selling for a family member.', E'Modes: auto, manual, averaging\nCuffs: S, M, L\nPower: AC or 4 x AA', 'Good', 'Apex, NC', 240.00, 1, NULL, 0, TRUE, '2026-04-20 15:55:00'),
(13, 5, 28, 'Vacutainer EDTA Tubes (Case of 1000)', '367861', 'Lavender-top K2EDTA blood collection tubes, sealed cases, long dating. New old stock; never put into service. Ships on a pallet; freight quoted separately.', E'Draw volume: 4 mL\nSize: 13 x 75 mm\nCount: 1000', 'New', 'Winston-Salem, NC', 140.00, 18, NULL, 0, TRUE, '2026-04-23 17:35:00'),
(19, 6, 14, 'Sagittal Saw', 'System 8 8208', 'Battery-powered sagittal saw handpiece with two batteries and charger. Demo unit in excellent condition. Decommissioned during an equipment upgrade.', E'Speed: 0-18,000 cpm\nBatteries: 2 x SmartLife\nAutoclavable: handpiece', 'Like New', 'Atlanta, GA', 4100.00, 1, NULL, 0, TRUE, '2026-04-25 13:25:00'),
(14, 8, 3, 'Patient Monitor', 'CARESCAPE B450', 'Modular patient monitor with PDM module, ECG, SpO2, NIBP and temperature. Demo unit in excellent condition. Local pickup available.', E'Display: 12.1 in touchscreen\nParameters: ECG, SpO2, NIBP, Temp, IBP\nBattery: 2 hr', 'Like New', 'Greenville, NC', 3450.00, 2, NULL, 0, TRUE, '2026-05-08 17:20:00'),
(21, 7, 10, 'Powered Air-Purifying Respirator', 'Versaflo TR-300+', 'PAPR kit with belt, battery, charger, breathing tube and two hoods. Demo unit in excellent condition. Includes original manual.', E'Battery: Li-ion, 8+ hr\nFilter: HE\nApproval: NIOSH', 'Like New', 'Nashville, TN', 985.00, 1, NULL, 0, TRUE, '2026-05-15 19:20:00'),
(17, 5, 33, 'Digital Stirring Hot Plate', 'PC-420D', 'Ceramic top stirring hot plate with digital display and external probe port. Refurbished and tested by our biomedical team. Cleaned and disinfected before shipping.', E'Top: 5 x 7 in ceramic\nTemp: up to 550 C\nStir: 60-1150 RPM', 'Refurbished', 'Columbia, SC', 425.00, 1, NULL, 0, TRUE, '2026-05-16 09:40:00'),
(12, 2, 21, 'Mobile Digital X-Ray System', 'Mobilett Mira Max', 'Battery-powered mobile radiography unit with wireless flat-panel detector. Used for a few weeks; no visible wear. Decommissioned during an equipment upgrade.', E'Generator: 35 kW\nDetector: 35 x 43 cm wireless\nBattery: motorized drive\nPower: 120 V', 'Like New', 'Greensboro, NC', 47750.00, 1, NULL, 0, TRUE, '2026-05-17 18:55:00'),
(19, 3, 14, 'Evacuation Stair Chair', 'Stair-PRO 6252', 'Stair chair with track system for descending stairs with one operator. Professionally refurbished with new wear parts.', E'Weight capacity: 500 lb\nWeight: 41 lb\nTracks: adjustable angle', 'Refurbished', 'Atlanta, GA', 1875.00, 1, NULL, 0, TRUE, '2026-05-28 10:45:00'),
(19, 2, 3, 'Portable Ultrasound System', 'LOGIQ e R7', 'Laptop-style ultrasound with convex and linear probes. Used in an emergency department. Heavy cosmetic wear, priced accordingly. Includes original manual.', E'Probes: 4C-RS convex, 12L-RS linear\nModes: B, M, color Doppler, PW Doppler\nDisplay: 15 in LCD\nBattery: 1 hr', 'Fair', 'Atlanta, GA', 6625.00, 1, NULL, 0, TRUE, '2026-06-09 19:55:00'),
(14, 3, 5, 'Med/Surg Hospital Bed', 'Advanta 2', 'Full-electric med/surg bed with integrated scale, bed exit alarm and nurse controls. Some scuffs on the housing; tested and working. Decommissioned during an equipment upgrade.', E'Height range: 15-31 in\nWeight capacity: 500 lb\nScale: integrated\nPower: 120 V', 'Good', 'Greenville, NC', 2425.00, 1, 45.00, 1, TRUE, '2026-07-08 20:50:00'),
(11, 10, 54, 'Combination Therapy System', 'Intelect Legend XT', 'Combination electrotherapy and 1/3.3 MHz ultrasound unit with cart. Light cosmetic wear, works as intended. Ships on a pallet; freight quoted separately.', E'Channels: 2 electrotherapy + ultrasound\nWaveforms: IFC, Premod, Russian, VMS\nUltrasound: 1 and 3.3 MHz', 'Good', 'Asheville, NC', 1500.00, 1, NULL, 0, TRUE, '2026-07-17 11:00:00'),
(10, 6, 36, 'Laceration Tray Instrument Set', 'Miltex Lac Tray', 'Reusable laceration set: needle holder, iris scissors, Adson forceps, hemostats. New in original packaging. Includes original manual.', E'Pieces: 7\nMaterial: German stainless steel\nAutoclavable: yes', 'New', 'Wilmington, NC', 195.00, 8, NULL, 0, TRUE, '2026-08-02 09:50:00'),
(17, 5, 8, 'CO2 Incubator', 'Heracell VIOS 160i', 'Direct heat CO2 incubator with 140 C high-heat sterilization cycle and copper interior. New in original packaging. Local pickup available.', E'Capacity: 165 L\nTemp range: ambient +3 to 55 C\nCO2 range: 0-20%', 'New', 'Columbia, SC', 6575.00, 1, NULL, 0, TRUE, '2026-08-11 19:10:00'),
(20, 1, 9, 'Quad Cane, Small Base', 'MDS86240', 'Aluminum quad cane with offset handle and non-slip rubber tips. New in original packaging.', E'Handle height: 29-38 in\nWeight capacity: 300 lb\nBase: small', 'New', 'Knoxville, TN', 22.99, 15, NULL, 0, TRUE, '2026-08-15 13:30:00'),
(21, 6, 39, 'Benchtop Autoclave', '2540EP', 'Semi-automatic autoclave with digital display and printer port. Some scuffs on the housing; tested and working. Local pickup available.', E'Chamber: 10 x 18 in\nCycles: unwrapped, wrapped, liquids\nPower: 120 V', 'Good', 'Nashville, TN', 3000.00, 1, NULL, 0, TRUE, '2026-09-18 19:05:00'),
(13, 5, 33, 'Serological Pipettes 10 mL (Case of 500)', 'Stripette 4488', 'Sterile, individually wrapped polystyrene serological pipettes. New in original packaging. Ships on a pallet; freight quoted separately.', E'Volume: 10 mL\nCount: 500\nSterile: yes, non-pyrogenic', 'New', 'Winston-Salem, NC', 98.99, 36, NULL, 0, TRUE, '2026-09-23 16:50:00'),
(19, 8, 3, 'Patient Monitor', 'CARESCAPE B450', 'Modular patient monitor with PDM module, ECG, SpO2, NIBP and temperature. Demo unit in excellent condition. Service history available on request.', E'Display: 12.1 in touchscreen\nParameters: ECG, SpO2, NIBP, Temp, IBP\nBattery: 2 hr', 'Like New', 'Atlanta, GA', 3925.00, 3, 81.00, 1, TRUE, '2026-09-26 08:35:00'),
(22, 5, 32, 'Thermal Cycler', 'C1000 Touch', 'PCR thermal cycler with 96-well fast reaction module and touchscreen. Some scuffs on the housing; tested and working. Ships on a pallet; freight quoted separately.', E'Block: 96-well\nRamp rate: up to 5 C/s\nGradient: 30-100 C', 'Good', 'Durham, NC', 3850.00, 2, NULL, 0, TRUE, '2026-10-11 18:25:00'),
(14, 6, 41, 'Electrosurgical Generator', 'Valleylab FT10', 'Energy platform with LigaSure vessel sealing and monopolar/bipolar outputs. Used for a few weeks; no visible wear.', E'Outputs: monopolar, bipolar, LigaSure\nMax output: 300 W\nDisplay: touchscreen', 'Like New', 'Greenville, NC', 11000.00, 1, NULL, 0, TRUE, '2026-10-30 19:35:00'),
(6, 1, 2, 'Rollator Walker with Seat', 'Nitro RTL10266', 'Euro-style rollator with padded seat, backrest, under-seat bag and loop locking brakes. Used for a few weeks; no visible wear. Service history available on request.', E'Handle height: 31-37 in\nSeat height: 22 in\nWeight capacity: 300 lb\nWeight: 18 lb', 'Like New', 'Raleigh, NC', 110.00, 4, 5.00, 1, TRUE, '2026-11-01 16:45:00'),
(5, 5, 7, 'Refrigerated Microcentrifuge', '5424 R', 'Refrigerated microcentrifuge with 24-place aerosol-tight rotor. Refurbished, passed full performance verification. Service history available on request.', E'Max speed: 15,000 RPM (21,130 x g)\nCapacity: 24 x 1.5/2.0 mL\nTemp range: -10 to 40 C', 'Refurbished', 'RTP, NC', 4150.00, 2, NULL, 0, TRUE, '2026-11-12 11:50:00'),
(24, 8, 46, 'AED Plus Defibrillator', 'AED Plus', 'Automated external defibrillator with Real CPR Help. New CPR-D-padz included. Barely used and cleaned; looks new. Cleaned and disinfected before shipping.', E'Energy: 120-200 J biphasic\nBatteries: 10 x 123A lithium\nRating: IP55', 'Like New', 'Kitty Hawk, NC', 1025.00, 2, 33.00, 3, TRUE, '2026-11-14 10:10:00'),
(12, 8, 3, 'Resting ECG System', 'MAC 5500 HD', '12-lead resting ECG with 12SL interpretation, trolley and acquisition module. Some scuffs on the housing; tested and working.', E'Leads: 12/15\nDisplay: 10.4 in\nPrinter: thermal A4', 'Good', 'Greensboro, NC', 3675.00, 1, NULL, 0, TRUE, '2026-11-18 20:25:00');
